116	    /**
117	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that key
118	     * originally created, so a retried create with the same key returns that owner instead
119	     * of creating a duplicate. Held in memory for the application's lifetime and keyed by the
120	     * raw header value.
121	     */
122	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
127	        boolean hasKey = idempotencyKey != null && !idempotencyKey.isBlank();
128	        if (hasKey) {
129	            Integer existingId = idempotentCreates.get(idempotencyKey);
130	            if (existingId != null) {
131	                Owner existing = this.clinicService.findOwnerById(existingId);
132	                if (existing != null) {
133	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
134	                }
135	            }
136	        }
137	        ResponseEntity<OwnerDto> response = createNewOwner(ownerFieldsDto);
138	        if (hasKey && response.getStatusCode() == HttpStatus.CREATED
139	            && response.getBody() != null && response.getBody().getId() != null) {
140	            idempotentCreates.putIfAbsent(idempotencyKey, response.getBody().getId());
141	        }
142	        return response;
143	    }
