145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
148	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
149	        if (currentOwner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        currentOwner.setAddress(ownerFieldsDto.getAddress());
153	        currentOwner.setCity(ownerFieldsDto.getCity());
154	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
155	        currentOwner.setLastName(ownerFieldsDto.getLastName());
156	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
157	        String email = ownerFieldsDto.getEmail();
158	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
159	        this.clinicService.saveOwner(currentOwner);
160	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
161	    }
