16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.time.Month;
23	import java.time.Period;
24	import java.util.Map;
25	import java.util.Set;
26	
27	/**
28	 * Pure derivations of an {@link Owner}'s read-only attributes.
29	 *
30	 * <p>Each method computes one derived value from an owner's own field values and
31	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
32	 * exposes these through thin {@code @Transient} getters that pass in the relevant
33	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
34	 * to describe its persistent state and relationships while its growing family of
35	 * derived attributes lives together in one place.
36	 */
37	final class OwnerDerivations {
38	
39	    /** Fixed city-to-region table used to derive {@link #region}. */
40	    private static final Map<String, String> CITY_REGION = Map.of(
41	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
42	
43	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
44	     *  {@link #region} in preference to the city. */
45	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
46	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
47	
48	    /** Fixed region-to-timezone table (IANA names) used to derive {@link #timezone}. */
49	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
50	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
51	
52	    /** Email domains that identify disposable, throw-away mailboxes, used to derive
53	     *  {@link #emailDomainIsDisposable(String)}. */
54	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
55	        "mailinator.com", "tempmail.com", "guerrillamail.com");
56	
57	    /** Fixed version tag mixed into the region and hashes that make up an owner's
58	     *  identifiers, so every version-2 identifier ({@link #memberId}, {@link #identityKey}
59	     *  and {@link #householdId}) differs from the value the same owner would have carried
60	     *  under version 1. It is confined to the identifiers: it never reaches the user-facing
61	     *  {@link #locality(String, String) locality}, {@link #timezone(String) timezone} or the
62	     *  region the owner segment derives from. */
63	    private static final String IDENTITY_VERSION_TAG = "V2";
64	
65	    private OwnerDerivations() {
66	    }
67	
68	    /**
69	     * The owner's locality, i.e. the canonical region it belongs to, derived directly from
70	     * the owner's own fields (see {@link #region(String, String)}). This is the plain,
71	     * user-facing region code (for example {@code NSW}): unlike the region embedded inside
72	     * the owner's identifiers it never carries the {@code V2} version tag. Because the
73	     * identifiers now mix that tag into their region they are no longer a source for the
74	     * plain locality, which is derived from the owner's fields directly.
75	     *
76	     * @return the canonical region string, or {@code "UNKNOWN"}
77	     */
78	    static String locality(String postcode, String city) {
79	        return region(postcode, city);
80	    }
81	
82	    /**
83	     * The canonical region derived for an owner from its own fields. The postcode is
84	     * consulted first: when it is present and falls within a known region's inclusive
85	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
86	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
87	     * known range does this fall back to the fixed city-to-region table
88	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
89	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
90	     * the same region for the known cities while disambiguating cities that share a name
91	     * via their postcode.
92	     *
93	     * @return the canonical region string, or {@code "UNKNOWN"}
94	     */
95	    static String region(String postcode, String city) {
96	        String byPostcode = regionForPostcode(postcode);
97	        if (byPostcode != null) {
98	            return byPostcode;
99	        }
100	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
101	    }
102	
103	    /**
104	     * The IANA timezone name derived from the given {@code locality} (a canonical
105	     * region) via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
106	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
107	     * {@code null} when the locality is not one of the known regions (for example
108	     * {@code "UNKNOWN"}).
109	     *
110	     * @return the IANA timezone name, or {@code null}
111	     */
112	    static String timezone(String locality) {
113	        return REGION_TIMEZONE.get(locality);
114	    }
115	
116	    /**
117	     * The region whose inclusive postcode range contains the given postcode, or
118	     * {@code null} when the postcode is absent, not a four-digit number, or in no
119	     * known range.
120	     */
121	    private static String regionForPostcode(String postcode) {
122	        if (postcode == null || !postcode.matches("\\d{4}")) {
123	            return null;
124	        }
125	        int value = Integer.parseInt(postcode);
126	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
127	            int[] range = entry.getValue();
128	            if (value >= range[0] && value <= range[1]) {
129	                return entry.getKey();
130	            }
131	        }
132	        return null;
133	    }
134	
135	    /**
136	     * Whether the given {@code postcode} is acceptable for the given {@code region}: an
137	     * absent postcode is always accepted, a present postcode must be exactly four
138	     * digits and, when the region has a known inclusive postcode range
139	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), fall within
140	     * it. A region with no known range (for example {@code "UNKNOWN"}) accepts any
141	     * four-digit postcode.
142	     *
143	     * @return {@code true} if the postcode is absent or valid for the region
144	     */
145	    static boolean postcodeMatchesRegion(String postcode, String region) {
146	        if (postcode == null) {
147	            return true;
148	        }
149	        if (!postcode.matches("\\d{4}")) {
150	            return false;
151	        }
152	        int[] range = REGION_POSTCODES.get(region);
153	        if (range == null) {
154	            return true;
155	        }
156	        int value = Integer.parseInt(postcode);
157	        return value >= range[0] && value <= range[1];
158	    }
159	
160	    /**
161	     * The owner's membership points, a non-negative score derived from its factors:
162	     * starting at 0, add 2 when an {@code email} is present, add 1 when
163	     * {@code namesakeCount} is 0, add 2 for a household of 3 or more (its
164	     * {@code householdSize}) and add 3 when the owner's tenure exceeds a year, measured as
165	     * the number of whole fiscal years elapsed from its {@code registrationDate} up to
166	     * {@code asOf} (the fiscal year starts on 1 July). Because a newly created owner has
167	     * zero elapsed fiscal years, it never earns the tenure points at creation.
168	     *
169	     * @return the membership points, 0 or more
170	     */
171	    static int membershipPoints(String email, Integer namesakeCount, Integer householdSize,
172	            LocalDate registrationDate, LocalDate asOf) {
173	        int points = 0;
174	        if (hasEmail(email)) {
175	            points += 2;
176	        }
177	        if (namesakeCount != null && namesakeCount == 0) {
178	            points += 1;
179	        }
180	        if (householdSize != null && householdSize >= 3) {
181	            points += 2;
182	        }
183	        if (tenureExceedsYear(registrationDate, asOf)) {
184	            points += 3;
185	        }
186	        return points;
187	    }
188	
189	    /**
190	     * The owner's membership level, a number from 1 to 4, mapped from its
191	     * {@link #membershipPoints(String, Integer, Integer, LocalDate, LocalDate) membership
192	     * points}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5 and level 4 for 6
193	     * or more.
194	     *
195	     * @return the membership level, from 1 to 4
196	     */
197	    static int membershipLevel(int points) {
198	        if (points <= 1) {
199	            return 1;
200	        }
201	        if (points <= 3) {
202	            return 2;
203	        }
204	        if (points <= 5) {
205	            return 3;
206	        }
207	        return 4;
208	    }
209	
210	    /**
211	     * The owner's membership level after applying its household level ceiling. The level
212	     * mapped from {@code points} (see {@link #membershipLevel(int)}) is returned unchanged
213	     * when {@code cap} is {@code null} (the owner joined no existing household), and
214	     * otherwise capped to at most {@code cap} — the ceiling assigned at creation, one above
215	     * the highest level then held by an existing household member — so a new owner can rise
216	     * to at most one level above its household.
217	     *
218	     * @return the capped membership level, from 1 to 4
219	     */
220	    static int membershipLevel(int points, Integer cap) {
221	        int level = membershipLevel(points);
222	        return cap == null ? level : Math.min(level, cap);
223	    }
224	
225	    /**
226	     * The owner's marketing segment, formatted {@code <TIER>_<AREA>}, one of
227	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
228	     * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when {@code membershipLevel} is 3
229	     * or more, otherwise {@code STANDARD}. AREA is {@code METRO} when {@code locality} is a
230	     * known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code REGIONAL}.
231	     *
232	     * @return the owner's segment as {@code <TIER>_<AREA>}
233	     */
234	    static String ownerSegment(int membershipLevel, String locality) {
235	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
236	        String area = REGION_TIMEZONE.containsKey(locality) ? "METRO" : "REGIONAL";
237	        return tier + "_" + area;
238	    }
239	
240	    /**
241	     * Whether the owner's tenure exceeds a year, i.e. at least one whole fiscal year has
242	     * elapsed from its {@code registrationDate} up to {@code asOf} (see
243	     * {@link #elapsedFiscalYears(LocalDate, LocalDate)}). This is the single tenure test
244	     * the tenure-driven membership derivations share, so they agree on exactly when an
245	     * owner has been a member for "over a year"; it is {@code false} whenever either date
246	     * is absent.
247	     */
248	    private static boolean tenureExceedsYear(LocalDate registrationDate, LocalDate asOf) {
249	        return registrationDate != null && asOf != null
250	            && elapsedFiscalYears(registrationDate, asOf) >= 1;
251	    }
252	
253	    /**
254	     * The number of whole fiscal years elapsed from {@code registrationDate} up to
255	     * {@code asOf}, i.e. the difference between the fiscal year that contains {@code asOf}
256	     * and the one that contains {@code registrationDate} (see {@link #fiscalYearOf(LocalDate)}).
257	     * Two dates in the same fiscal year yield {@code 0}, so an owner registered in the
258	     * current fiscal year has zero tenure until the next 1 July rollover.
259	     */
260	    static int elapsedFiscalYears(LocalDate registrationDate, LocalDate asOf) {
261	        return fiscalYearOf(asOf) - fiscalYearOf(registrationDate);
262	    }
263	
264	    /**
265	     * The fiscal year that contains the given date, as a four-digit calendar year. The
266	     * fiscal year runs from 1 July to 30 June and is labelled by the calendar year in
267	     * which it ends: a date from January to June falls in the fiscal year of its own
268	     * calendar year, while a date from July to December falls in the next calendar year's
269	     * fiscal year (e.g. {@code 2026-05-03 -> 2026} but {@code 2026-08-03 -> 2027}).
270	     */
271	    static int fiscalYearOf(LocalDate date) {
272	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
273	    }
274	
275	    /**
276	     * The owner's fiscal year, formatted {@code FY<YY>} where YY is the last two digits of
277	     * the fiscal year (see {@link #fiscalYearOf(LocalDate)}) that contains its
278	     * business-day-adjusted {@code registrationDate}, e.g. {@code FY27} for a registration
279	     * date of {@code 2026-08-03}. Returns {@code null} when no registration date is present.
280	     *
281	     * @return the fiscal year as {@code FY<YY>}, or {@code null}
282	     */
283	    static String fiscalYear(LocalDate registrationDate) {
284	        if (registrationDate == null) {
285	            return null;
286	        }
287	        return "FY" + fiscalYearSegment(registrationDate);
288	    }
289	
290	    /**
291	     * The two-digit fiscal-year segment for a registration date: the last two digits of the
292	     * fiscal year that contains it (see {@link #fiscalYearOf(LocalDate)}), zero-padded, e.g.
293	     * {@code "27"} for a registration date of {@code 2026-08-03}. This is the single
294	     * definition the fiscal-year-bearing identifiers share, so they agree on exactly which
295	     * two-digit year they carry.
296	     *
297	     * @return the two-digit fiscal-year segment
298	     */
299	    static String fiscalYearSegment(LocalDate registrationDate) {
300	        return String.format("%02d", fiscalYearOf(registrationDate) % 100);
301	    }
302	
303	    /**
304	     * The owner's salutation, formed as {@code title + ' ' + lastName} when a
305	     * {@code title} is present, or just the {@code lastName} when no title is supplied.
306	     * A {@code null} or blank title contributes nothing, yielding the bare last name.
307	     *
308	     * @return the composed salutation
309	     */
310	    static String salutation(String title, String lastName) {
311	        if (title == null || title.isBlank()) {
312	            return lastName;
313	        }
314	        return title + " " + lastName;
315	    }
316	
317	    /**
318	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
319	     * is present, otherwise {@code "PHONE"}.
320	     *
321	     * @return {@code "EMAIL"} or {@code "PHONE"}
322	     */
323	    static String contactPreference(String email) {
324	        if (hasEmail(email)) {
325	            return "EMAIL";
326	        }
327	        return "PHONE";
328	    }
329	
330	    /**
331	     * Whether the owner has an email address on file, i.e. its {@code email} is present
332	     * and not blank. This is the single presence test the email-driven derivations share
333	     * (a membership-level factor and the {@link #contactPreference(String) contact
334	     * preference}), so they agree on exactly what counts as "has an email".
335	     */
336	    private static boolean hasEmail(String email) {
337	        return email != null && !email.isBlank();
338	    }
339	
340	    /**
341	     * The domain component of an email address: the lower-cased run after its final
342	     * {@code '@'}, or the empty string when the value is absent or carries no {@code '@'}.
343	     * This is the single domain extraction the email-domain derivations share, so they
344	     * agree on exactly what an address's domain is; each then classifies that domain in
345	     * its own way.
346	     *
347	     * @return the lower-cased email domain, or the empty string when there is none
348	     */
349	    static String emailDomain(String email) {
350	        if (email == null) {
351	            return "";
352	        }
353	        int at = email.lastIndexOf('@');
354	        if (at < 0) {
355	            return "";
356	        }
357	        return email.substring(at + 1).toLowerCase();
358	    }
359	
360	    /**
361	     * Whether the email's {@link #emailDomain(String) domain} is one of the known
362	     * disposable, throw-away mailbox domains ({@code mailinator.com}, {@code tempmail.com},
363	     * {@code guerrillamail.com}). An address without a domain (absent, or carrying no
364	     * {@code '@'}) is treated as having no disposable domain.
365	     *
366	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
367	     */
368	    static boolean emailDomainIsDisposable(String email) {
369	        return DISPOSABLE_EMAIL_DOMAINS.contains(emailDomain(email));
370	    }
371	
372	    /**
373	     * Whether the owner should be flagged as risky, i.e. any one of its risk signals
374	     * holds: it is a possible duplicate ({@code possibleDuplicate}), its email domain is
375	     * disposable-adjacent (on the disposable-domain blocklist, see
376	     * {@link #emailDomainIsDisposable(String)}), or its city was over its soft capacity at
377	     * creation ({@code capacityWarning}). The two persisted flags are treated as
378	     * {@code false} when absent, so the risk flag is {@code false} for an owner with no
379	     * signal set.
380	     *
381	     * @return {@code true} when any risk signal holds, otherwise {@code false}
382	     */
383	    static boolean riskFlag(Boolean possibleDuplicate, String email, Boolean capacityWarning) {
384	        return Boolean.TRUE.equals(possibleDuplicate)
385	            || emailDomainIsDisposable(email)
386	            || Boolean.TRUE.equals(capacityWarning);
387	    }
388	
389	    /**
390	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
391	     * given {@code value}, processed right-to-left with every second digit doubled (and
392	     * reduced by 9 when the double exceeds 9). Non-digit characters are ignored, and an
393	     * absent or digit-free value yields {@code 0}.
394	     *
395	     * @return the Luhn check digit, from 0 to 9
396	     */
397	    static int checkDigit(String value) {
398	        int sum = 0;
399	        boolean doubleDigit = true;
400	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
401	            char c = value.charAt(i);
402	            if (c < '0' || c > '9') {
403	                continue;
404	            }
405	            int d = c - '0';
406	            if (doubleDigit) {
407	                d *= 2;
408	                if (d > 9) {
409	                    d -= 9;
410	                }
411	            }
412	            sum += d;
413	            doubleDigit = !doubleDigit;
414	        }
415	        return (10 - (sum % 10)) % 10;
416	    }
417	
418	    /**
419	     * The owner's age band, derived from its {@code birthDate} measured against its
420	     * {@code registrationDate}: {@code "MINOR"} when the owner is under 18 on the
421	     * registration date, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
422	     * over. The age is the number of whole years between the two dates. Returns
423	     * {@code null} when either date is absent, so no band is reported for an owner
424	     * without a supplied birth date.
425	     *
426	     * @return {@code "MINOR"}, {@code "ADULT"}, {@code "SENIOR"}, or {@code null}
427	     */
428	    static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
429	        if (birthDate == null || registrationDate == null) {
430	            return null;
431	        }
432	        int age = Period.between(birthDate, registrationDate).getYears();
433	        if (age < 18) {
434	            return "MINOR";
435	        }
436	        if (age < 65) {
437	            return "ADULT";
438	        }
439	        return "SENIOR";
440	    }
441	
442	    /**
443	     * The single derived key used for duplicate detection: the lower-case hexadecimal
444	     * SHA-256 digest of {@code 'V2' + '|' + normalizedTelephone + '|' + lowerEmail + '|' +
445	     * soundex(lastName)}, mixing in the fixed {@code V2} version tag so the key differs from
446	     * the version-1 key the same owner would have produced. The telephone is the owner's
447	     * stored (E.164-normalised)
448	     * telephone (or the empty string when absent), the email is the stored (lower-cased)
449	     * email or the empty string when absent, and the last-name component is the
450	     * {@link #soundex(String) Soundex code} of the owner's last name. Because the
451	     * telephone is part of the key, two owners sharing a last name and postcode but with
452	     * different telephones have different keys.
453	     *
454	     * @return the owner's identity key, a 64-character lower-case hex string
455	     */
456	    static String identityKey(String telephone, String email, String lastName) {
457	        String tel = telephone == null ? "" : telephone;
458	        String mail = email == null ? "" : email.toLowerCase();
459	        return sha256Hex(IDENTITY_VERSION_TAG + "|" + tel + "|" + mail + "|" + soundex(lastName));
460	    }
461	
462	    /**
463	     * The American Soundex code of the given name: its first letter followed by three
464	     * digits derived from the remaining consonants ({@code b,f,p,v -> 1};
465	     * {@code c,g,j,k,q,s,x,z -> 2}; {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5};
466	     * {@code r -> 6}), where adjacent letters mapping to the same digit (including when
467	     * separated only by {@code h} or {@code w}) are coded once, vowels ({@code a,e,i,o,u},
468	     * and {@code y}) separate otherwise-identical digits, and the result is zero-padded or
469	     * truncated to exactly four characters. Non-letters are ignored; an absent or
470	     * letter-free value yields the empty string.
471	     *
472	     * @param value the name to encode (may be {@code null})
473	     * @return the four-character Soundex code, or the empty string
474	     */
475	    static String soundex(String value) {
476	        if (value == null) {
477	            return "";
478	        }
479	        StringBuilder letters = new StringBuilder();
480	        for (char c : value.toUpperCase().toCharArray()) {
481	            if (c >= 'A' && c <= 'Z') {
482	                letters.append(c);
483	            }
484	        }
485	        if (letters.length() == 0) {
486	            return "";
487	        }
488	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
489	        char previousDigit = soundexDigit(letters.charAt(0));
490	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
491	            char letter = letters.charAt(i);
492	            char digit = soundexDigit(letter);
493	            if (digit != '0' && digit != previousDigit) {
494	                code.append(digit);
495	            }
496	            if (letter != 'H' && letter != 'W') {
497	                previousDigit = digit;
498	            }
499	        }
500	        while (code.length() < 4) {
501	            code.append('0');
502	        }
503	        return code.toString();
504	    }
505	
506	    /**
507	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a letter that
508	     * carries no Soundex digit (the vowels {@code a,e,i,o,u}, and {@code y,h,w}).
509	     */
510	    private static char soundexDigit(char c) {
511	        return switch (c) {
512	            case 'B', 'F', 'P', 'V' -> '1';
513	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
514	            case 'D', 'T' -> '3';
515	            case 'L' -> '4';
516	            case 'M', 'N' -> '5';
517	            case 'R' -> '6';
518	            default -> '0';
519	        };
520	    }
521	
522	    /**
523	     * The owner's unified member id, formatted {@code <REGION><FY><HASH8><CHK>}: REGION is the
524	     * {@link #identifierRegion(String, String) version-2 region embedded inside the owner's
525	     * identifiers} (the plain region derived from its postcode, falling back to its city, with the
526	     * fixed {@code V2} version tag mixed in), FY is the two-digit
527	     * {@link #fiscalYearSegment(LocalDate) fiscal-year segment} of its {@code registrationDate},
528	     * HASH8 is the {@link #hash8(String, String) HASH8} of its telephone and last name, and CHK
529	     * is a single {@link #checkDigit(String) Luhn check digit} computed over the decimal digits
530	     * of {@code <REGION><FY><HASH8>} (e.g. {@code NSWV2279F86D0817}). This unifies the former
531	     * customer code and membership number into one identifier.
532	     *
533	     * @return the member id
534	     */
535	    static String memberId(String postcode, String city, String telephone, String lastName,
536	            LocalDate registrationDate) {
537	        String base = identifierRegion(postcode, city) + fiscalYearSegment(registrationDate)
538	            + hash8(telephone, lastName);
539	        return base + checkDigit(base);
540	    }
541	
542	    /**
543	     * The version-2 region component embedded inside the owner's identifiers — currently the
544	     * leading {@code <REGION>} of its {@link #memberId(String, String, String, String, LocalDate)
545	     * member id} — being the plain region derived from the owner's own fields via
546	     * {@link #region(String, String)} with the fixed {@code V2} version tag mixed in. Held as its
547	     * own derivation, kept deliberately distinct from the user-facing
548	     * {@link #locality(String, String) locality} region, so the region carried inside identifiers
549	     * has a single home and can evolve independently of the plain region reported to callers. The
550	     * mixed-in tag is confined to the identifiers, so no version-1 identifier region is produced
551	     * again while the plain locality stays untagged.
552	     *
553	     * @return the version-2 region embedded inside the owner's identifiers
554	     */
555	    private static String identifierRegion(String postcode, String city) {
556	        return region(postcode, city) + IDENTITY_VERSION_TAG;
557	    }
558	
559	    /**
560	     * The HASH8 component of the region-and-hash identity: the first eight upper-case
561	     * hexadecimal characters of the SHA-256 digest of the owner's normalised
562	     * {@code telephone} concatenated with its {@code lastName} (e.g. {@code 9F86D081}).
563	     * Held as its own derivation so the identity's hash component has a single definition
564	     * rather than being spelled out at each identifier that embeds it.
565	     *
566	     * @return the eight upper-case hexadecimal HASH8 characters
567	     */
568	    static String hash8(String telephone, String lastName) {
569	        return sha256Hex(telephone + lastName).substring(0, 8).toUpperCase();
570	    }
571	
572	    /**
573	     * The stable identifier for the household an owner belongs to, derived
574	     * deterministically from its {@code normalizedLastName} and {@code postcode} so that
575	     * every owner sharing a last name and postcode resolves to the same value. It is the
576	     * first twelve lower-case hexadecimal characters of the SHA-256 digest of
577	     * {@code 'V2' + '|' + normalizedLastName + '|' + postcode} (an absent postcode contributes
578	     * the empty string), mixing in the fixed {@code V2} version tag so the household id differs
579	     * from the version-1 value the same household would have produced.
580	     *
581	     * @return the household identifier
582	     */
583	    static String householdId(String normalizedLastName, String postcode) {
584	        String pc = postcode == null ? "" : postcode;
585	        return sha256Hex(IDENTITY_VERSION_TAG + "|" + normalizedLastName + "|" + pc).substring(0, 12);
586	    }
587	
588	    /**
589	     * Reduce an address to its canonical stored form: trim and collapse runs of
590	     * whitespace to a single space, upper-case, and expand common abbreviations
591	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
592	     * they appear as whole words. The result is what is stored, returned and used
593	     * for every household comparison; it is idempotent, so re-normalising an
594	     * already-normalised address leaves it unchanged.
595	     *
596	     * @param value the raw address (may be {@code null})
597	     * @return the normalised address, or the empty string if {@code value} is
598	     *         {@code null} or blank
599	     */
600	    static String normalizeAddress(String value) {
601	        String collapsed = collapseWhitespace(value).toUpperCase();
602	        if (collapsed.isEmpty()) {
603	            return "";
604	        }
605	        String[] tokens = collapsed.split(" ");
606	        for (int i = 0; i < tokens.length; i++) {
607	            tokens[i] = switch (tokens[i]) {
608	                case "ST" -> "STREET";
609	                case "RD" -> "ROAD";
610	                case "AVE" -> "AVENUE";
611	                default -> tokens[i];
612	            };
613	        }
614	        return String.join(" ", tokens);
615	    }
616	
617	    /**
618	     * Trim the given value and collapse every internal run of whitespace to a single
619	     * space, treating an absent value as empty. This is the single whitespace
620	     * normalisation the name and address normalisers share, so they agree on what
621	     * counts as insignificant whitespace; each then applies its own casing (and, for
622	     * addresses, whole-word abbreviation expansion).
623	     *
624	     * @param value the raw value (may be {@code null})
625	     * @return the trimmed, whitespace-collapsed value, or the empty string when
626	     *         {@code value} is {@code null}
627	     */
628	    static String collapseWhitespace(String value) {
629	        if (value == null) {
630	            return "";
631	        }
632	        return value.trim().replaceAll("\\s+", " ");
633	    }
634	
635	    /**
636	     * The SHA-256 digest of the UTF-8 bytes of the given value, as a lower-case
637	     * hexadecimal string. Callers take the prefix and case they need.
638	     */
639	    static String sha256Hex(String value) {
640	        try {
641	            byte[] digest = MessageDigest.getInstance("SHA-256")
642	                .digest(value.getBytes(StandardCharsets.UTF_8));
643	            StringBuilder hex = new StringBuilder(digest.length * 2);
644	            for (byte b : digest) {
645	                hex.append(String.format("%02x", b));
646	            }
647	            return hex.toString();
648	        } catch (NoSuchAlgorithmException e) {
649	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
650	        }
651	    }
652	}
